import {depotEase} from './depot-motion.js?v=depot-v16';
// A short bloom bridges the receding frame to the documentary title.
export function paintDepotTitle(c,t,f){const start=(f.depotDuration??58)-6.2,age=t-start;if(age<0)return;const bloom=Math.exp(-Math.pow((age-.55)/.22,2));if(bloom>.002){c.save();c.globalCompositeOperation='screen';c.globalAlpha=bloom*.88;const light=c.createRadialGradient(500,240,10,500,240,650);light.addColorStop(0,'#fffdf6');light.addColorStop(.45,'#fff9edb0');light.addColorStop(1,'#fff0');c.fillStyle=light;c.fillRect(0,0,960,540);c.restore()}const q=depotEase((age-.65)/2.4);if(!q)return;c.save();c.textAlign='center';c.textBaseline='middle';c.globalAlpha=depotEase((age-.7)/.8);c.font='400 27px Arial';c.fillStyle='#f7f8fa';c.shadowColor='#f2f8ff66';c.shadowBlur=7;c.fillText('THE INSANE TRUE STORY OF',480,230);c.shadowBlur=0;const parts=[['ADIDAS','#25a8df'],[' AND ','#fafafa'],['PUMA','#f34630']];c.font='800 62px Arial';const widths=parts.map(([word])=>c.measureText(word).width),total=widths.reduce((a,b)=>a+b,0);let cursor=480-total/2,index=0;c.textAlign='left';for(let part=0;part<parts.length;part++){const [word,color]=parts[part];for(const letter of word){const width=c.measureText(letter).width,delay=(index*7%9)*.025,r=depotEase((q-delay)/Math.max(.1,1-delay)),x=cursor+(1-r)*Math.sin(index*5.7)*300,y=300+(1-r)*Math.cos(index*4.3)*220;c.save();c.translate(x,y);c.rotate((1-r)*Math.sin(index*3)*.24);const scale=1+(1-r)*1.7;c.scale(scale,scale);c.globalAlpha=r;c.fillStyle=color;c.filter=`blur(${(1-r)*7}px)`;c.fillText(letter,0,0);c.restore();cursor+=width;index++}}c.restore()}
